    21  /// Projects trusted request headers into the canonical OCLA context.
    22  ///
    23  /// The auth middleware establishes trust before provider handlers run. Legacy,
    24  /// partial, duplicated or malformed header sets remain unmanaged; the proxy
    25  /// never invents lineage and never rejects otherwise valid provider traffic.
    26  pub(super) fn from_trusted_headers(
    27      headers: &HeaderMap,
    28      exact_bounded_body: &[u8],
    29  ) -> Option<OclaRequestContext> {
    30      let request_id = exact_id(headers, REQUEST_ID_HEADER)?;
    31      let session_id = exact_id(headers, SESSION_ID_HEADER)?;
    32      let agent_id = exact_id(headers, AGENT_ID_HEADER)?;
    33  
    34      Some(OclaRequestContext {
    35          request_id,
    36          session_id,
    37          agent_id,
    38          content_ref: content_ref_v1(exact_bounded_body),
    39          tenant_id: None,
    40          trace_id: "tr-unit".into(),
    41      })
    42  }
    43  
    44  /// Admits caller-supplied lineage only after the proxy auth guard has marked
    45  /// the request as gateway-trusted. Provider-key fallback remains unmanaged;
    46  /// its upstream credential authenticates the provider, not OCLA metadata.
    47  pub(super) fn from_trusted_request(
    48      parts: &Parts,
    49      exact_bounded_body: &[u8],
    50  ) -> Option<OclaRequestContext> {
    51      parts
    52          .extensions
    53          .get::<super::gateway_identity::TrustedGatewayRequest>()
    54          .and_then(|_| from_trusted_headers(&parts.headers, exact_bounded_body))
    55  }
