fn exact_u64(headers: &HeaderMap, name: &'static str) -> Result<Option<u64>, ()> {
    let mut values = headers.get_all(name).iter();
    let Some(value) = values.next() else {
        return Ok(None);
    };
    if values.next().is_some() {
        return Err(());
    }
    let value = value.to_str().map_err(|_| ())?;
    if value.is_empty() || !value.bytes().all(|b| b.is_ascii_digit()) {
        return Err(());
    }
    value.parse::<u64>().map(Some).map_err(|_| ())
}

/// Admission check for OCLA budget metadata on trusted proxy requests.
/// Requests without budget metadata are admitted. Invalid metadata yields 400;
/// exhausted or insufficient budgets yield 429.
pub(super) fn admit_budget(parts: &Parts, exact_bounded_body: &[u8]) -> Result<(), u16> {
    if parts
        .extensions
        .get::<super::gateway_identity::TrustedGatewayRequest>()
        .is_none()
    {
        return Ok(());
    }
    let remaining = exact_u64(&parts.headers, BUDGET_REMAINING_HEADER).map_err(|()| 400u16)?;
    let requested = exact_u64(&parts.headers, BUDGET_REQUESTED_HEADER).map_err(|()| 400u16)?;
    let Some(remaining) = remaining else {
        return if requested.is_some() { Err(400) } else { Ok(()) };
    };
    let needed = requested.unwrap_or_else(|| (exact_bounded_body.len() as u64).div_ceil(4).max(1));
    if remaining == 0 || needed > remaining {
        return Err(429);
    }
    Ok(())
}

